def group(rs):
 dist=Counter(x['complete_columns'] for x in rs);peer=lambda z:next(t for t in Z if t!=z and next(n for n in range(1,50) if n2z(n)==t)%6==next(n for n in range(1,50) if n2z(n)==z)%6);cases=[]
